.cen-post-wrap { margin-bottom: 16px; background: var(--bg-card); border-radius: 12px; padding: 14px; border: 1px solid rgba(0,0,0,0.03); }
.cen-post-head { font-size: 14px; font-weight: 600; color: var(--c-blue-dark); margin-bottom: 6px; }
