<div id="Z_Config_Static_Micro" class="cen-v11-light"></div>

<script>
(function(){
    const Mm_anchor = document.getElementById('Z_Config_Static_Micro');
    if(!Mm_anchor) return;

    // 缩写标识符输入示范
    const cold_tank = `$1
    `;

    const Ks_data = {
        avatar: '', thought: '',
        ootd: {}, br: [], todo: [], posts: [], ss: [], gcs: [], dms: []
    };

    let state = 'root';
    let curPost = null, curGc = null, curDm = null;

    cold_tank.trim().split('\n').forEach(line => {
        if(!line.trim()) return;
        const parts = line.split('|').map(s => s.trim());
        const tag = parts[0];

        if(tag === 'AVA') Ks_data.avatar = parts[1];
        if(tag === 'OS') Ks_data.thought = parts[1]; 
        if(tag === 'FAV') Ks_data.ootd.fav = { val: parts[1], desc: parts[2] };
        if(tag === 'CLS') Ks_data.ootd.clothes = parts[1];
        if(tag === 'ACT') Ks_data.ootd.action = parts[1];

        if(tag === 'BR') Ks_data.br.push({ title: parts[1], desc: parts[2] });
        if(tag === 'TODO') Ks_data.todo.push({ title: parts[1], desc: parts[2] });

        if(tag === 'POST') {
          state = 'post';
          curPost = { title: parts[1], body: parts[2], cmts: [] };
          Ks_data.posts.push(curPost);
        }
        if(tag === 'CMT' && state === 'post' && curPost) {
          curPost.cmts.push({ name: parts[1], msg: parts[2] });
        }

        if(tag === 'SS') {
          Ks_data.ss.push({ title: parts[1], body: parts[2] });
        }

        if(tag === 'GC') {
          state = 'gc';
          curGc = { name: parts[1], msgs: [] };
          Ks_data.gcs.push(curGc);
        }
        if(tag === 'DM') {
          state = 'dm';
          curDm = { name: parts[1], msgs: [] };
          Ks_data.dms.push(curDm);
        }
        if(tag === 'MSG') {
          if(state === 'gc' && curGc) curGc.msgs.push({ name: parts[1], msg: parts[2] });
          if(state === 'dm' && curDm) curDm.msgs.push({ name: parts[1], msg: parts[2] });
        }
    });

    let html = '';

    html += `
    <div class="cen-v11-trigger" onclick="this.nextElementSibling.nextElementSibling.style.display = this.nextElementSibling.nextElementSibling.style.display === 'block' ? 'none' : 'block'">
        <img class="cen-v11-avatar" src="${Ks_data.avatar}">
        <div class="cen-v11-bubble">
          <div class="cen-v11-name">神的低语</div>
          <div class="cen-v11-desc">${Ks_data.thought}</div>
        </div>
    </div>
    <div class="cen-v11-divider"></div>
    <div class="cen-v11-panel">
    `;

    if(Object.keys(Ks_data.ootd).length > 0) {
        html += `<div class="cen-v11-sec"><div class="cen-v11-title">OOTD</div><div class="cen-ootd-box">`;
        if(Ks_data.ootd.fav) html += `<div class="cen-ootd-row"><div class="cen-ootd-label">FAV</div><div class="cen-ootd-val"><span style="color:var(--c-blue-base);font-weight:600">${Ks_data.ootd.fav.val}</span> <span style="margin:0 6px;color:var(--border-light)">|</span> <span style="color:var(--text-mut)">${Ks_data.ootd.fav.desc}</span></div></div>`;
        if(Ks_data.ootd.clothes) html += `<div class="cen-ootd-row"><div class="cen-ootd-label">OUTFIT</div><div class="cen-ootd-val">${Ks_data.ootd.clothes}</div></div>`;
        if(Ks_data.ootd.action) html += `<div class="cen-ootd-row"><div class="cen-ootd-label">ACTION</div><div class="cen-ootd-val">${Ks_data.ootd.action}</div></div>`;
        html += `</div></div>`;
    }

    if(Ks_data.br.length > 0) {
        html += `<div class="cen-v11-sec"><div class="cen-v11-title">BROWSE RECORD</div><div class="cen-ootd-box">`;
        Ks_data.br.forEach(b => {
          html += `<div class="cen-ootd-row" style="flex-direction:column;gap:6px;"><div style="color:var(--text-main);font-weight:600;font-size:13px">${b.title}</div><div style="color:var(--text-mut);font-size:12px">${b.desc}</div></div>`;
        });
        html += `</div></div>`;
    }

    if(Ks_data.todo.length > 0) {
        html += `<div class="cen-v11-sec"><div class="cen-v11-title">TIMELINE</div><div class="cen-time-axis">`;
        Ks_data.todo.forEach(t => {
          html += `<div class="cen-time-node"><div class="cen-time-t">${t.title}</div><div class="cen-time-d">${t.desc}</div></div>`;
        });
        html += `</div></div>`;
    }

    if(Ks_data.posts.length > 0) {
        html += `<div class="cen-v11-sec"><div class="cen-v11-title">FORUM POSTS</div><div class="cen-scroll">`;
        Ks_data.posts.forEach(p => {
          html += `<div class="cen-post-wrap"><div class="cen-post-head">${p.title}</div><div class="cen-post-body">${p.body}</div>`;
          p.cmts.forEach(c => { html += `<div class="cen-msg-item"><span class="cen-hl-light">${c.name}</span><span class="cen-msg-text">${c.msg}</span></div>`; });
          html += `</div>`;
        });
        html += `</div></div>`;
    }

    if(Ks_data.ss.length > 0) {
        Ks_data.ss.forEach(s => {
          html += `<div class="cen-v11-sec"><div class="cen-v11-title">${s.title}</div><div class="cen-scroll" style="font-size:13px;color:var(--text-mut);line-height:1.6;">${s.body}</div></div>`;
        });
    }

    if(Ks_data.gcs.length > 0 || Ks_data.dms.length > 0) {
        html += `<div class="cen-v11-sec" style="display:flex;gap:14px;">`;
        if(Ks_data.gcs.length > 0) {
          html += `<div style="flex:1;min-width:0;"><div class="cen-scroll">`;
          Ks_data.gcs.forEach(g => {
          html += `<div style="margin-bottom:14px;"><div class="cen-v11-title" style="font-size:11px;color:var(--c-blue-base)">[ ${g.name} ]</div>`;
          g.msgs.forEach(m => { html += `<div class="cen-msg-item"><span class="cen-hl-light">${m.name}</span><span class="cen-msg-text">${m.msg}</span></div>`; });
          html += `</div>`;
          });
          html += `</div></div>`;
        }
        if(Ks_data.dms.length > 0) {
          html += `<div style="flex:1;min-width:0;"><div class="cen-scroll">`;
          Ks_data.dms.forEach(d => {
          html += `<div style="margin-bottom:14px;"><div class="cen-v11-title" style="font-size:11px;color:var(--c-blue-base)">[ ${d.name} ]</div>`;
          d.msgs.forEach(m => { html += `<div class="cen-msg-item"><span class="cen-hl-light">${m.name}</span><span class="cen-msg-text">${m.msg}</span></div>`; });
          html += `</div>`;
          });
          html += `</div></div>`;
        }
        html += `</div>`;
    }

    html += `<div class="cen-wm">៷>ᴗ<៷</div></div>`;
    Mm_anchor.innerHTML = html;

})();
</script>
